const item = $json;

// Formatear el mensaje
$json.message = `ALERTA DE INVENTARIO:

El item '${item.item_name}' (Código: ${item.item_code}) en el almacén ${item.whs_code} tiene una demanda estimada de ${item.predicted_quantity} unidades para el próximo mes.

Se recomienda revisar el stock y planificar una orden de compra.
`;

return $json;
